function applyWeight(svg: string, weight: number): string {
  const sw = (abIconWeightStroke as Record<number, number>)[weight] ?? weight;
  const val = String(sw);
  return svg.replace(/stroke-width="[^"]*"/g, `stroke-width="${val}"`);
}

/**
 * Get SVG markup for an AbIcon name.
 * @param name Material snake_case icon name (e.g. "home", "arrow_back")
 * @param variant "outlined" (default) or "filled" (falls back to outlined if missing)
 * @param options.weight optional 100–700 (outlined). Default 200. Filled stay solid.
 */
export function getAbIconSvg(
  name: string,
  variant: "outlined" | "filled" = "outlined",
  options?: AbIconSvgOptions,
): string | undefined {
  const entry = (abIconSvg as Record<string, AbIconSvgEntry | undefined>)[name];
  if (!entry) return undefined;
  let svg = variant === "filled" ? (entry.filled ?? entry.outlined) : entry.outlined;
  if (variant !== "filled") {
    const weight = options?.weight ?? abIconDefaultWeight;
    svg = applyWeight(svg, Number(weight));
  }
  return svg;
}

